#include "s61_binary_deeper_quartic_field_20261101.hpp"
#include <array>
#include <chrono>
using Mon=array<int,7>;
int main(int argc,char**argv){assert(argc==4 && string(argv[3])=="3");fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{int degree=argc>3?stoi(argv[3]):4;vector<Mon>m2,m4,shifts;for(int a=0;a<7;a++)for(int b=a;b<7;b++){Mon m{};m[a]++;m[b]++;m2.push_back(m);}if(degree==4){for(int a=0;a<7;a++)for(int b=a;b<7;b++)for(int c=b;c<7;c++)for(int d=c;d<7;d++){Mon m{};m[a]++;m[b]++;m[c]++;m[d]++;m4.push_back(m);}shifts=m2;}else{assert(degree==3);for(int a=0;a<7;a++)for(int b=a;b<7;b++)for(int c=b;c<7;c++){Mon m{};m[a]++;m[b]++;m[c]++;m4.push_back(m);}for(int a=0;a<7;a++){Mon m{};m[a]++;shifts.push_back(m);}}map<Mon,int>ix;for(int i=0;i<(int)m4.size();i++)ix[m4[i]]=i;vector<Row>A,B;vector<int>pivs;ifstream in(argv[1]);int nr,nc;in>>nr>>nc;for(int i=0;i<nr;i++){int nn;in>>nn;Row q;for(int k=0;k<nn;k++){int j;in>>j;Rat x;readpoly(in,x.n);readpoly(in,x.d);q.emplace(j,std::move(x));}for(auto&shift:shifts){Row row;for(auto&[j,v]:q){Mon m=shift;for(int k=0;k<7;k++)m[k]+=m2[j][k];row.emplace(ix.at(m),v);}A.push_back(std::move(row));}}
ofstream pf(string(argv[2])+".pivots");auto start=chrono::steady_clock::now();while(true){int best=-1,col=-1;long score=0;for(int i=0;i<int(A.size());i++)for(auto&[j,v]:A[i]){long z=fmpq_mpoly_length(v.n,ctx)+fmpq_mpoly_length(v.d,ctx);if(best<0||z<score){best=i;col=j;score=z;}}if(best<0)break;Row row=std::move(A[best]);A[best].clear();Rat pivot=row[col];pf<<best<<' '<<col<<'\n';writepoly(pf,pivot.n);writepoly(pf,pivot.d);pf.flush();for(auto&[j,v]:row)v=divi(v,pivot);for(auto&other:A){auto it=other.find(col);if(it==other.end())continue;Rat factor=it->second;for(auto&[j,v]:row){Rat z=sub(other[j],mul(factor,v));if(z.zero())other.erase(j);else other[j]=std::move(z);}}pivs.push_back(col);B.push_back(std::move(row));cerr<<"rank "<<B.size()<<" terms "<<score<<" row "<<best<<" col "<<col<<" sec "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}
assert(B.size()==48);for(auto&row:A)assert(row.empty());ofstream out(argv[2]);out<<B.size()<<" "<<m4.size()<<"\n";for(int i=0;i<int(B.size());i++){out<<pivs[i]<<' '<<B[i].size()<<'\n';for(auto&[j,v]:B[i]){out<<j<<'\n';writepoly(out,v.n);writepoly(out,v.d);}}}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
